public static class EntryPath {
 public const string Computer="shell:::{20D04FE0-3AEA-1069-A2D8-08002B30309D}",RecycleBin="shell:::{645FF040-5081-101B-9F08-00AA002F954E}";
 public static string Normalize(string path){if(String.IsNullOrWhiteSpace(path))throw new InvalidDataException("入口为空");string p=path.Trim();if(String.Equals(p,Computer,StringComparison.OrdinalIgnoreCase)||String.Equals(p,Computer.Substring(6),StringComparison.OrdinalIgnoreCase)||String.Equals(p,"shell:MyComputerFolder",StringComparison.OrdinalIgnoreCase))return Computer;if(String.Equals(p,RecycleBin,StringComparison.OrdinalIgnoreCase)||String.Equals(p,RecycleBin.Substring(6),StringComparison.OrdinalIgnoreCase)||String.Equals(p,"shell:RecycleBinFolder",StringComparison.OrdinalIgnoreCase))return RecycleBin;return System.IO.Path.GetFullPath(path);}
 public static bool IsShell(string path){return String.Equals(path,Computer,StringComparison.OrdinalIgnoreCase)||String.Equals(path,RecycleBin,StringComparison.OrdinalIgnoreCase);}
 public static bool Exists(string path){return IsShell(path)||File.Exists(path)||Directory.Exists(path);}
 public static string Title(string path){return path==Computer?"此电脑":path==RecycleBin?"回收站":System.IO.Path.GetFileName(path.TrimEnd('\\'));}
}
public static class ShellDrop {
 public const string Format="Shell IDList Array";
 public static bool CanRead(IDataObject data){return data.GetDataPresent(DataFormats.FileDrop)||data.GetDataPresent(Format);}
 static int PidlLength(byte[] bytes,int offset,int min){if(offset<min||offset>bytes.Length-2)throw new InvalidDataException("Shell PIDL偏移越界");int pos=offset;while(pos<=bytes.Length-2){int size=BitConverter.ToUInt16(bytes,pos);if(size==0)return pos-offset+2;if(size<2||size>bytes.Length-pos)break;pos+=size;}throw new InvalidDataException("Shell PIDL记录不完整");}
 public static string[] Decode(byte[] bytes){if(bytes==null||bytes.Length<10||bytes.Length>16*1024*1024)throw new InvalidDataException("Shell拖入数据无效");int count=BitConverter.ToInt32(bytes,0);if(count<0||count>20000||count>(bytes.Length-8)/4)throw new InvalidDataException("Shell拖入数量无效");int header=8+4*count,parent=BitConverter.ToInt32(bytes,4);PidlLength(bytes,parent,header);var result=new List<string>();IntPtr memory=Marshal.AllocCoTaskMem(bytes.Length);try{Marshal.Copy(bytes,0,memory,bytes.Length);for(int i=0;i<count;i++){int child=BitConverter.ToInt32(bytes,8+4*i);PidlLength(bytes,child,header);string path=Native.ShellItemPath(IntPtr.Add(memory,parent),IntPtr.Add(memory,child));if(!String.IsNullOrWhiteSpace(path)){try{path=EntryPath.Normalize(path);if(EntryPath.Exists(path)&&!result.Contains(path,StringComparer.OrdinalIgnoreCase))result.Add(path);}catch{}}}}finally{Marshal.FreeCoTaskMem(memory);}return result.ToArray();}
 public static string[] Read(IDataObject data){var paths=new List<string>();try{if(data.GetDataPresent(Format)){object value=data.GetData(Format);byte[] bytes=value as byte[];var stream=value as MemoryStream;if(stream!=null)bytes=stream.ToArray();if(bytes!=null)paths.AddRange(Decode(bytes));}}catch{}try{if(data.GetDataPresent(DataFormats.FileDrop))paths.AddRange((string[])data.GetData(DataFormats.FileDrop));}catch{}return paths.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
 public static byte[] FromPaths(string[] paths){var items=paths.Select(Native.ShellPidlBytes).ToArray();int header=8+4*items.Length,offset=header+2;using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write(items.Length);writer.Write(header);foreach(var item in items){writer.Write(offset);offset+=item.Length;}writer.Write((ushort)0);foreach(var item in items)writer.Write(item);return stream.ToArray();}}
}
