 public List<Group> Groups=new List<Group>{new Group{Id="inbox",Name="未分组"}};
 public List<Item> Items=new List<Item>();
 public int DockVersion=0;public List<string> DockPins=new List<string>();public List<string> DockRunningOrder=new List<string>();
 public bool ShowNames=false;
 public string Active="all";public double Opacity=.14,Width=740,Height=390,PanelGlass=100;public bool Collapsed=false,Topmost=false;public int Screen=0;
