public static class DesktopStorage {
 public static string Desktop {get{return Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);}}
 public static bool Production(Store store){string main=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DeskBox");string root=System.IO.Path.GetFullPath(store.Root).TrimEnd('\\');return String.Equals(root,main,StringComparison.OrdinalIgnoreCase)||String.Equals(root,System.IO.Path.Combine(main,"files-widget"),StringComparison.OrdinalIgnoreCase);}
 public static bool Under(string path,string root){string r=System.IO.Path.GetFullPath(root).TrimEnd('\\');string p=System.IO.Path.GetFullPath(path).TrimEnd('\\');return String.Equals(p,r,StringComparison.OrdinalIgnoreCase)||p.StartsWith(r+"\\",StringComparison.OrdinalIgnoreCase);}
 static string Unique(string root,string name){string ext=System.IO.Path.GetExtension(name),stem=System.IO.Path.GetFileNameWithoutExtension(name);for(int n=0;n<10000;n++){string candidate=System.IO.Path.Combine(root,n==0?name:stem+" ("+(n+1)+")"+ext);if(!File.Exists(candidate)&&!Directory.Exists(candidate))return candidate;}throw new IOException("桌面同名项目过多");}
 static void CheckTree(string path){var attr=File.GetAttributes(path);if((attr&FileAttributes.ReparsePoint)!=0)throw new IOException("不复制链接或联接目录："+path);if((attr&FileAttributes.Directory)!=0)foreach(string child in Directory.EnumerateFileSystemEntries(path))CheckTree(child);}
 static void CopyTree(string source,string dest){Directory.CreateDirectory(dest);foreach(string child in Directory.EnumerateFileSystemEntries(source)){string target=System.IO.Path.Combine(dest,System.IO.Path.GetFileName(child));if(Directory.Exists(child))CopyTree(child,target);else File.Copy(child,target,false);}}
 public static string Import(string source,string root,string suggested=null){source=EntryPath.Normalize(source);if(EntryPath.IsShell(source)||Under(source,root))return source;if(!EntryPath.Exists(source))throw new FileNotFoundException("原文件不存在",source);if(!Directory.Exists(root))throw new DirectoryNotFoundException("桌面目录不可用："+root);CheckTree(source);bool isDir=Directory.Exists(source);string name=System.IO.Path.GetFileName(source.TrimEnd('\\'));if(!isDir&&String.Equals(System.IO.Path.GetExtension(source),".exe",StringComparison.OrdinalIgnoreCase)){string shortcut=Unique(root,System.IO.Path.GetFileNameWithoutExtension(name)+".lnk");using(var reserved=new FileStream(shortcut,FileMode.CreateNew,FileAccess.Write,FileShare.None)){}try{Native.CreateShortcut(shortcut,source,"");return shortcut;}catch{try{File.Delete(shortcut);}catch{}throw;}}if(!String.IsNullOrWhiteSpace(suggested)&&!isDir&&String.Equals(System.IO.Path.GetExtension(name),".lnk",StringComparison.OrdinalIgnoreCase)){foreach(char c in System.IO.Path.GetInvalidFileNameChars())suggested=suggested.Replace(c,'_');name=suggested.EndsWith(".lnk",StringComparison.OrdinalIgnoreCase)?suggested:suggested+".lnk";}string destination=Unique(root,name);if(!isDir){File.Copy(source,destination,false);return destination;}string tmp=System.IO.Path.Combine(root,".rushbin-copy-"+Guid.NewGuid().ToString("N"));try{CopyTree(source,tmp);Directory.Move(tmp,destination);return destination;}catch{if(Directory.Exists(tmp)&&Under(tmp,root))try{Directory.Delete(tmp,true);}catch{}throw;}}
}
public class Store {
 public Model Data=new Model();public string Root,Warning="";public bool NeedsDockMigration;public string FilePath{get{return System.IO.Path.Combine(Root,"data.json");}}
 JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};
 public Store(string root){Root=root;Directory.CreateDirectory(root);Load();Validate(Data);}
 public void Validate(Model m){
  if(m==null||m.Items==null||m.Groups==null)throw new InvalidDataException("不是有效的 DeskBox 配置");
  if(m.Items.Count>20000||m.Groups.Count>500)throw new InvalidDataException("配置超出数量限制");
  m.Groups=m.Groups.Where(x=>x!=null&&!String.IsNullOrWhiteSpace(x.Id)&&x.Id!="all").GroupBy(x=>x.Id).Select(x=>x.First()).ToList();
  if(!m.Groups.Any(x=>x.Id=="inbox"))m.Groups.Insert(0,new Group{Id="inbox",Name="未分组"});
  foreach(var g in m.Groups)if(String.IsNullOrWhiteSpace(g.Name))g.Name="分组";
  m.Items=m.Items.Where(x=>x!=null&&!String.IsNullOrWhiteSpace(x.Id)&&!String.IsNullOrWhiteSpace(x.Path)).GroupBy(x=>x.Id).Select(x=>x.First()).ToList();
  if(m.DockVersion<1){m.DockPins=m.Items.Take(6).Select(x=>x.Id).ToList();m.DockVersion=1;}
  if(m.DockPins==null)m.DockPins=new List<string>();m.DockPins=m.DockPins.Where(id=>m.Items.Any(x=>x.Id==id)).Distinct().ToList();
  foreach(var i in m.Items){if(!m.Groups.Any(g=>g.Id==i.Group))i.Group="inbox";if(String.IsNullOrWhiteSpace(i.Name))i.Name=System.IO.Path.GetFileName(i.Path);}
  if(m.Active!="all"&&!m.Groups.Any(x=>x.Id==m.Active))m.Active="all";
  if(Double.IsNaN(m.Width)||Double.IsInfinity(m.Width))m.Width=900;if(Double.IsNaN(m.Opacity)||Double.IsInfinity(m.Opacity))m.Opacity=.8;
  if(Double.IsNaN(m.Height)||Double.IsInfinity(m.Height))m.Height=390;
  m.Width=Math.Max(500,Math.Min(10000,m.Width));m.Height=Math.Max(250,Math.Min(10000,m.Height));m.Opacity=Math.Max(.04,Math.Min(.85,m.Opacity));if(Double.IsNaN(m.PanelGlass)||Double.IsInfinity(m.PanelGlass))m.PanelGlass=100;m.PanelGlass=Math.Max(0,Math.Min(100,m.PanelGlass));
  if(Double.IsNaN(m.PanelX)||Double.IsInfinity(m.PanelX))m.PanelX=-99999;if(Double.IsNaN(m.PanelY)||Double.IsInfinity(m.PanelY))m.PanelY=-99999;
  if(Double.IsNaN(m.StatusX)||Double.IsInfinity(m.StatusX))m.StatusX=-99999;if(Double.IsNaN(m.StatusY)||Double.IsInfinity(m.StatusY))m.StatusY=-99999;
 }
 public void Load(){foreach(var p in new[]{FilePath,FilePath+".bak"}){if(!File.Exists(p))continue;try{var m=json.Deserialize<Model>(File.ReadAllText(p,Encoding.UTF8));bool migrate=m.DockVersion<1;Validate(m);Data=m;NeedsDockMigration=migrate;if(p!=FilePath)Warning="主配置无法读取，已从备份恢复。损坏文件保留在配置目录。";return;}catch{Warning="配置无法读取，已使用空收纳箱；原配置保留在配置目录。";}}}
 public void Save(){
  Validate(Data);if(Warning!=""&&File.Exists(FilePath)){File.Copy(FilePath,FilePath+".recovered-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),false);Warning="";}
  string temp=FilePath+".tmp";using(var f=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None))using(var w=new StreamWriter(f,new UTF8Encoding(false))){w.Write(json.Serialize(Data));w.Flush();f.Flush(true);}
  if(File.Exists(FilePath))File.Replace(temp,FilePath,FilePath+".bak",true);else File.Move(temp,FilePath);
 }
 public string NewGroup(string name){name=(name??"").Trim();if(name.Length==0)throw new InvalidDataException("请填写分组名称");if(name.Length>30)throw new InvalidDataException("分组名称最多 30 个字");if(Data.Groups.Any(x=>String.Equals(x.Name,name,StringComparison.OrdinalIgnoreCase)))throw new InvalidDataException("已经存在同名分组");var g=new Group{Name=name};Data.Groups.Add(g);Save();return g.Id;}
 public void DeleteGroup(string id){if(id=="inbox")throw new InvalidDataException("未分组不能删除");foreach(var i in Data.Items.Where(x=>x.Group==id))i.Group="inbox";Data.Groups.RemoveAll(x=>x.Id==id);if(Data.Active==id)Data.Active="inbox";Save();}
 public int Add(string[] paths,string group,out int rejected){
  rejected=0;int count=0;if(!Data.Groups.Any(x=>x.Id==group))group="inbox";
  foreach(string p in paths){try{string source=EntryPath.Normalize(p);if(!EntryPath.Exists(source)){rejected++;continue;}var old=Data.Items.FirstOrDefault(x=>String.Equals(x.Path,source,StringComparison.OrdinalIgnoreCase)||String.Equals(x.SourcePath,source,StringComparison.OrdinalIgnoreCase));string path=old==null&&DesktopStorage.Production(this)?DesktopStorage.Import(source,DesktopStorage.Desktop):source;if(old!=null){if(Data.Active!="all")old.Group=group;continue;}string name=EntryPath.Title(path);Data.Items.Add(new Item{Path=path,SourcePath=String.Equals(path,source,StringComparison.OrdinalIgnoreCase)?"":source,Name=String.IsNullOrEmpty(name)?path:name,Group=group});count++;}catch{rejected++;}}
  Save();return count;
 }
 public IEnumerable<Item> Filter(string query){return Data.Items.Where(x=>(Data.Active=="all"||x.Group==Data.Active)&&(String.IsNullOrEmpty(query)||(x.Name+" "+x.Path).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0));}
 public void Move(string id,string group){var i=Data.Items.FirstOrDefault(x=>x.Id==id);if(i==null||!Data.Groups.Any(x=>x.Id==group))return;i.Group=group;Save();}
 public void Reorder(string source,string target){var a=Data.Items.FirstOrDefault(x=>x.Id==source);var b=Data.Items.FirstOrDefault(x=>x.Id==target);if(a==null||b==null||a==b)return;Data.Items.Remove(a);Data.Items.Insert(Data.Items.IndexOf(b),a);Save();}
 public bool ReorderInView(string source,IList<string> view,int slot){if(view==null||view.Count<2||view.Distinct().Count()!=view.Count)return false;int from=view.IndexOf(source);if(from<0||view.Any(id=>!Data.Items.Any(item=>item.Id==id)))return false;slot=Math.Max(0,Math.Min(view.Count,slot));int destination=slot-(from<slot?1:0);if(destination==from)return false;var itemToMove=Data.Items.First(item=>item.Id==source);var remaining=view.Where(id=>id!=source).ToList();Data.Items.Remove(itemToMove);int index=destination<remaining.Count?Data.Items.FindIndex(item=>item.Id==remaining[destination]):Data.Items.FindIndex(item=>item.Id==remaining[remaining.Count-1])+1;Data.Items.Insert(index,itemToMove);Save();return true;}
 public void Pin(string id,bool pin){if(pin&&Data.Items.Any(x=>x.Id==id)&&!Data.DockPins.Contains(id))Data.DockPins.Add(id);if(!pin)Data.DockPins.Remove(id);Save();}
 public void OrderPin(string source,string target){if(source==target||!Data.DockPins.Contains(source)||!Data.DockPins.Contains(target))return;Data.DockPins.Remove(source);Data.DockPins.Insert(Data.DockPins.IndexOf(target),source);Save();}
 public static bool MoveDockOrder(List<string> order,string source,string target,bool after){if(source==target||!order.Contains(source))return false;var before=order.ToArray();order.Remove(source);int index=order.IndexOf(target);order.Insert(index<0?(after?order.Count:0):index+(after?1:0),source);return !before.SequenceEqual(order);}
 public int ImportPinnedLinks(IEnumerable<string> paths){var oldPins=Data.DockPins.ToList();var imported=new List<string>();var identities=Data.Items.ToDictionary(x=>x.Id,x=>Native.LinkIdentity(x.Path));foreach(string path in paths){if(!File.Exists(path))continue;var identity=Native.LinkIdentity(path);var item=Data.Items.FirstOrDefault(x=>String.Equals(identities[x.Id],identity,StringComparison.OrdinalIgnoreCase));if(item==null){string target=DesktopStorage.Production(this)?DesktopStorage.Import(path,DesktopStorage.Desktop,TaskbarLinks.Title(path)):path;item=new Item{Path=target,SourcePath=String.Equals(path,target,StringComparison.OrdinalIgnoreCase)?"":path,Name=TaskbarLinks.Title(path),Group="inbox"};Data.Items.Add(item);identities[item.Id]=identity;}if(!imported.Contains(item.Id))imported.Add(item.Id);}Data.DockPins=imported.Concat(oldPins).Distinct().ToList();Save();return imported.Count;}
}

public static class TaskbarLinks {
 static Dictionary<string,string> names=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
 public static string Title(string path){string title;return names.TryGetValue(path,out title)?title:Native.LinkTitle(path);}
 public static List<byte[]> Decode(byte[] data){var links=new List<byte[]>();int offset=0;while(offset<data.Length){if(data.Length-offset<4)throw new InvalidDataException("任务栏记录尾部不完整");int size=BitConverter.ToInt32(data,offset);offset+=4;if(size<76||size>data.Length-offset||BitConverter.ToInt32(data,offset)!=76||data[offset+4]!=1||data[offset+5]!=0x14)throw new InvalidDataException("不支持的任务栏记录格式");var link=new byte[size];Buffer.BlockCopy(data,offset,link,0,size);links.Add(link);offset+=size;}return links;}
 public static string[] Read(string root){string folder=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),@"Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar");string[] originals=Directory.Exists(folder)?Directory.GetFiles(folder,"*.lnk"):new string[0];var titles=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string path in originals)titles[Native.LinkIdentity(path)]=System.IO.Path.GetFileNameWithoutExtension(path);byte[] bytes=null;using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband")){if(key!=null)bytes=key.GetValue("FavoritesResolve") as byte[];}var links=bytes!=null&&bytes.Length>0?Decode(bytes):originals.Select(File.ReadAllBytes).ToList();string dir=System.IO.Path.Combine(root,"TaskbarLinks");Directory.CreateDirectory(dir);var paths=new List<string>();foreach(var link in links){string hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(link)).Replace("-","");string path=System.IO.Path.Combine(dir,hash+".lnk");File.WriteAllBytes(path,link);for(int depth=0;depth<8;depth++){string target=Native.ShortcutTarget(path);if(!String.Equals(System.IO.Path.GetExtension(target),".lnk",StringComparison.OrdinalIgnoreCase)||!File.Exists(target)||String.Equals(target,path,StringComparison.OrdinalIgnoreCase))break;File.WriteAllBytes(path,File.ReadAllBytes(target));}string title;names[path]=titles.TryGetValue(Native.LinkIdentity(path),out title)?title:Native.LinkTitle(path);paths.Add(path);}return paths.ToArray();}
}

public static class Native {
 delegate bool EnumDesktopWindow(IntPtr h,IntPtr state);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumDesktopWindow callback,IntPtr state);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindowEx(IntPtr parent,IntPtr after,string name,string title);
 [DllImport("user32.dll")]public static extern IntPtr GetShellWindow();
 [DllImport("user32.dll")]static extern IntPtr GetWindow(IntPtr h,uint command);
 [DllImport("user32.dll",EntryPoint="GetWindowLongPtrW")]static extern IntPtr GetLong64(IntPtr h,int index);
 [DllImport("user32.dll",EntryPoint="GetWindowLongW")]static extern int GetLong32(IntPtr h,int index);
 [DllImport("user32.dll",EntryPoint="SetWindowLongPtrW",SetLastError=true)]static extern IntPtr SetLong64(IntPtr h,int index,IntPtr value);
 [DllImport("user32.dll",EntryPoint="SetWindowLongW",SetLastError=true)]static extern int SetLong32(IntPtr h,int index,int value);
 [DllImport("user32.dll")]public static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr h,StringBuilder text,int count);
 [DllImport("user32.dll")]static extern IntPtr GetAncestor(IntPtr h,uint flags);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint process);
 [DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);
 [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll")]public static extern bool IsWindowEnabled(IntPtr h);
 [DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int command);
 static IntPtr ReadLong(IntPtr h,int index){return IntPtr.Size==8?GetLong64(h,index):new IntPtr(GetLong32(h,index));}
 static void WriteLong(IntPtr h,int index,IntPtr value){if(IntPtr.Size==8)SetLong64(h,index,value);else SetLong32(h,index,value.ToInt32());}
 public static void DesktopWidget(Window window,bool desktopOwner=true){
  if((Program.ResizeCheck&&window is Box)||(Program.StatusCheck&&window is StatusWidget)||(Program.PanelCheck&&!Program.DockInputCheck&&window is DockBar))return;
  IntPtr h=new WindowInteropHelper(window).Handle;if(h==IntPtr.Zero)return;
  WidgetLayers.Register(window);long before=ReadLong(h,-20).ToInt64(),after=(before|0x80L)&~0x40000L;bool changed=false;
  if(window is ControlCenter)after|=0x08000000L;
  if(window is DockBar&&desktopOwner){after|=0x08000000L;if(Program.DockInputCheck)after=(after|0x40000L)&~0x80L;if(before!=after)WriteLong(h,-20,new IntPtr(after));if(GetWindow(h,4)!=IntPtr.Zero)WriteLong(h,-8,IntPtr.Zero);if(((DockBar)window).HoldShown||((DockBar)window).AttentionShown||WidgetLayers.Raised(window)){SetWindowPos(h,new IntPtr(-1),0,0,0,0,0x213);return;}if(!Program.DockInputCheck&&(ReadLong(h,-20).ToInt64()&8)!=0)SetWindowPos(h,new IntPtr(-2),0,0,0,0,0x213);AnchorDock(window);return;}
  if(before!=after){WriteLong(h,-20,new IntPtr(after));changed=true;}
  if(desktopOwner&&GetWindow(h,4)!=IntPtr.Zero){WriteLong(h,-8,IntPtr.Zero);changed=true;}
  if(changed)SetWindowPos(h,IntPtr.Zero,0,0,0,0,0x37);
 }
 public static bool ToolWindow(Window window){IntPtr h=new WindowInteropHelper(window).Handle;long style=ReadLong(h,-20).ToInt64();return (style&0x80)!=0&&(style&0x40000)==0&&!window.ShowInTaskbar;}
 public static void PreviewStyle(Window window){var h=new WindowInteropHelper(window).Handle;long style=(ReadLong(h,-20).ToInt64()|0x08000080L)&~0x40000L;if(Program.RunningProbe)style=(style|0x40000L)&~0x80L;WriteLong(h,-20,new IntPtr(style));PanelCorners(window);}
 public static IntPtr DesktopSurface(){IntPtr result=IntPtr.Zero;EnumWindows((h,state)=>{var name=new StringBuilder(128);GetClassName(h,name,name.Capacity);if((name.ToString()=="Progman"||name.ToString()=="WorkerW")&&FindWindowEx(h,IntPtr.Zero,"SHELLDLL_DefView",null)!=IntPtr.Zero){result=h;return false;}return true;},IntPtr.Zero);return result==IntPtr.Zero?GetShellWindow():result;}
 public static void AnchorDock(Window window){if(Program.PanelCheck||WidgetLayers.Raised(window)||(window is DockBar&&(((DockBar)window).HoldShown||((DockBar)window).AttentionShown)))return;IntPtr h=new WindowInteropHelper(window).Handle,desktop=DesktopSurface();if(h==IntPtr.Zero||desktop==IntPtr.Zero)return;IntPtr previous=GetWindow(desktop,3);if(previous==h)return;if(previous!=IntPtr.Zero&&(ReadLong(previous,-20).ToInt64()&8)!=0)previous=IntPtr.Zero;SetWindowPos(h,previous,0,0,0,0,0x213);}
 public static bool DockAnchored(Window window){IntPtr h=new WindowInteropHelper(window).Handle,desktop=DesktopSurface();return h!=IntPtr.Zero&&desktop!=IntPtr.Zero&&GetWindow(desktop,3)==h&&(ReadLong(h,-20).ToInt64()&8)==0&&GetWindow(h,4)==IntPtr.Zero;}
 public static bool IndependentWidget(Window window){var h=new WindowInteropHelper(window).Handle;return h!=IntPtr.Zero&&GetWindow(h,4)==IntPtr.Zero&&ToolWindow(window);}
 public static void PlaceAboveDesktop(Window window){if(!window.IsVisible||window.Topmost)return;var h=new WindowInteropHelper(window).Handle;var desktop=DesktopSurface();if(h==IntPtr.Zero||desktop==IntPtr.Zero||GetWindow(desktop,3)==h)return;var previous=GetWindow(desktop,3);if(previous==h)return;SetWindowPos(h,previous,0,0,0,0,0x213);}
