// Button Click occurs on release. Cancel it after a drag or the second press
// of a double click, without preventing keyboard activation or context menus.
// A desktop dock deliberately does not activate. Handle pointer release without
// ButtonBase's keyboard-focus attempt, while keeping its normal keyboard Click.
public static class DeferredDiagnostics {
 static readonly System.Collections.Concurrent.ConcurrentDictionary<string,string> pending=new System.Collections.Concurrent.ConcurrentDictionary<string,string>();static int scheduled;
 public static void Write(string path,string value){pending[path]=value;if(Interlocked.CompareExchange(ref scheduled,1,0)==0)ThreadPool.QueueUserWorkItem(o=>Drain());}
 static void Drain(){try{foreach(var pair in pending.ToArray()){string value;if(pending.TryRemove(pair.Key,out value))try{File.WriteAllText(pair.Key,value,Encoding.UTF8);}catch{}}}finally{Interlocked.Exchange(ref scheduled,0);if(!pending.IsEmpty&&Interlocked.CompareExchange(ref scheduled,1,0)==0)ThreadPool.QueueUserWorkItem(o=>Drain());}}
}
