public sealed class IconMotion {
 public sealed class Node {public Button Button;public Image Image;public ScaleTransform Scale=new ScaleTransform(1,1);}
 public readonly List<Node> Nodes=new List<Node>();DispatcherTimer timer;int selected=-1;bool suspended;
 public IconMotion(){timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(16)};timer.Tick+=(o,e)=>{if(!Step(selected))timer.Stop();};}
 public void Clear(){timer.Stop();selected=-1;Nodes.Clear();}
 public void Stop(){timer.Stop();}
 public void Reset(){timer.Stop();selected=-1;foreach(var node in Nodes){node.Scale.ScaleX=node.Scale.ScaleY=1;Panel.SetZIndex(node.Button,0);}}
 public void Suspend(bool value){suspended=value;Select(-1);}
 public void Add(Button button,Image image){var node=new Node{Button=button,Image=image};int index=Nodes.Count;Nodes.Add(node);image.RenderTransformOrigin=new Point(.5,.5);image.RenderTransform=node.Scale;button.MouseEnter+=(o,e)=>{if(!suspended)Select(index);};button.MouseLeave+=(o,e)=>{if(selected==index)Select(-1);};}
 void Select(int index){selected=index;Step(index);timer.Start();}
 bool Step(int index){bool moving=false;for(int i=0;i<Nodes.Count;i++){var n=Nodes[i];double target=i==index?1.38:1;double value=index>=0&&i!=index?1:n.Scale.ScaleX+(target-n.Scale.ScaleX)*.24;if(Math.Abs(value-target)<.001)value=target;moving|=value!=target;n.Scale.ScaleX=n.Scale.ScaleY=value;Panel.SetZIndex(n.Button,i==index?1:0);}return moving;}
 public double[] Preview(int index,int frames){timer.Stop();for(int i=0;i<frames;i++)Step(index);return Nodes.Select(n=>n.Scale.ScaleX).ToArray();}
}
