  var screens=Forms.Screen.AllScreens;int n=Math.Max(0,Math.Min(screens.Length-1,S.Data.Screen));var a=screens[n].WorkingArea;double scale=1;if(source!=null&&source.CompositionTarget!=null)scale=source.CompositionTarget.TransformToDevice.M11;
  MaxWidth=Math.Max(330,a.Width/scale-28);MaxHeight=Math.Max(240,a.Height/scale-28);MinWidth=Math.Min(500,MaxWidth);MinHeight=Math.Min(250,MaxHeight);Width=Math.Min(S.Data.Width,MaxWidth);Height=Math.Min(S.Data.Height,MaxHeight);
