public sealed class DesktopLayer {
 Box box;DockBar dock;DispatcherTimer timer;IntPtr previousForeground,previousShell;
 public DesktopLayer(Box b,DockBar d){box=b;dock=d;WidgetLayers.WatchExternalClicks();Refresh(true);timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(400)};timer.Tick+=(o,e)=>Refresh(false);timer.Start();Application.Current.Exit+=(o,e)=>timer.Stop();}
 void Refresh(bool force){
  var shell=Native.GetShellWindow();var foreground=Native.GetForegroundWindow();CodexActivation.ObserveForeground(foreground);var shots=Program.Shots;if(shots!=null)Native.DesktopWidget(shots);Native.DesktopWidget(box);Native.DesktopWidget(dock);var status=Program.Status;if(status!=null)Native.DesktopWidget(status);var center=Program.Control;if(center!=null)Native.DesktopWidget(center);var files=Program.Files;if(files!=null)Native.DesktopWidget(files);
  if(Native.DesktopForeground()){if(shots!=null)Native.RestoreOnDesktop(shots);Native.RestoreOnDesktop(dock);Native.RestoreOnDesktop(box);if(status!=null)Native.RestoreOnDesktop(status);if(center!=null)Native.RestoreOnDesktop(center);if(files!=null)Native.RestoreOnDesktop(files);}
  if(force||foreground!=previousForeground||shell!=previousShell){
   if(!Native.OwnForeground())WidgetLayers.ExternalForeground();if(!Native.OwnForeground()&&Native.IsWindowEnabled(new WindowInteropHelper(box).Handle)){Native.LowerToDesktop(box);Native.LowerToDesktop(dock);if(Program.Shots!=null)Native.LowerToDesktop(Program.Shots);if(status!=null)Native.LowerToDesktop(status);if(center!=null)Native.LowerToDesktop(center);if(files!=null&&!files.Held)WidgetLayers.Desktop(files);}
  }
  if(force||foreground!=previousForeground||shell!=previousShell)box.Backdrop.Update();if(center!=null)center.UpdateLayer();if(files!=null){files.Material.Update();files.Record();}Native.AnchorDock(dock);if(force||foreground!=previousForeground||shell!=previousShell){try{File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"desktop-widget-state.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),shellHandle=shell.ToInt64(),dock=Native.WidgetInfo(dock),panel=Native.WidgetInfo(box),scope="本程序实际样式及最后一次层级维护完成后的桌面锚点，不记录其他窗口标题"}),Encoding.UTF8);}catch{}}previousForeground=foreground;previousShell=shell;
 }
}
