public sealed class DockAttention:IDisposable {
 [StructLayout(LayoutKind.Sequential)]public struct FlashInfo {public uint cbSize;public IntPtr hwnd;public uint flags,count,timeout;}
 [DllImport("user32.dll")]public static extern bool FlashWindowEx(ref FlashInfo info);
 [DllImport("user32.dll",SetLastError=true)]static extern bool RegisterShellHookWindow(IntPtr h);
 [DllImport("user32.dll")]static extern bool DeregisterShellHookWindow(IntPtr h);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int RegisterWindowMessage(string name);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 [DllImport("user32.dll")]static extern bool IsWindow(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,uint pid);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool QueryFullProcessImageName(IntPtr h,uint flags,StringBuilder path,ref uint size);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 public sealed class Pending {public string Id,Executable;public IntPtr Window;public long Started;}
 readonly Dictionary<string,string> targets=new Dictionary<string,string>();readonly Dictionary<IntPtr,long> stopped=new Dictionary<IntPtr,long>();
 public readonly Dictionary<string,Pending> PendingApps=new Dictionary<string,Pending>();
 readonly DockBar dock;HwndSource source;IntPtr handle;DispatcherTimer poll;int shellMessage;bool disposed;public bool Registered;public int FlashEvents,MatchedEvents,StopRequests;public bool Enabled=true;
 public DockAttention(DockBar owner){dock=owner;try{string options=System.IO.Path.Combine(Program.S.Root,"dock-attention-options.json");if(File.Exists(options))Enabled=new JavaScriptSerializer().Deserialize<Dictionary<string,bool>>(File.ReadAllText(options))["enabled"];}catch{} }
 public static string Executable(IntPtr h){uint pid;GetWindowThreadProcessId(h,out pid);if(pid==0)return "";IntPtr process=OpenProcess(0x1000,false,pid);if(process==IntPtr.Zero)return "";try{uint length=32768;var path=new StringBuilder((int)length);return QueryFullProcessImageName(process,0,path,ref length)?path.ToString():"";}finally{CloseHandle(process);}}
 public static string Target(string path){try{string identity=Native.LinkIdentity(path);int split=identity.IndexOf('|');string target=split<0?identity:identity.Substring(0,split);return String.Equals(System.IO.Path.GetExtension(target),".exe",StringComparison.OrdinalIgnoreCase)?System.IO.Path.GetFullPath(target):"";}catch{return "";}}
 public static bool Matches(string target,string executable){if(String.IsNullOrEmpty(target)||String.IsNullOrEmpty(executable))return false;if(CodexActivation.MatchesIdentity(target+"|")&&CodexActivation.OfficialExecutable(executable))return true;if(String.Equals(target,executable,StringComparison.OrdinalIgnoreCase))return true;string name=System.IO.Path.GetFileName(target);if(!new[]{"QQ.exe","Weixin.exe","WeChat.exe"}.Contains(name,StringComparer.OrdinalIgnoreCase)||!String.Equals(name,System.IO.Path.GetFileName(executable),StringComparison.OrdinalIgnoreCase))return false;string folder=System.IO.Path.GetDirectoryName(target).TrimEnd('\\')+"\\";return executable.StartsWith(folder,StringComparison.OrdinalIgnoreCase);}
 public void Refresh(){targets.Clear();foreach(var item in Program.S.Data.Items.Where(i=>Program.S.Data.DockPins.Contains(i.Id)).Concat(dock.DynamicItems)){string target=Target(item.Path);if(target!="")targets[item.Id]=target;}bool changed=false;foreach(string id in PendingApps.Keys.Where(id=>!targets.ContainsKey(id)).ToArray()){PendingApps.Remove(id);changed=true;}if(changed)dock.WakeAttention();Record();}
 public void Start(HwndSource value){source=value;handle=value.Handle;shellMessage=RegisterWindowMessage("SHELLHOOK");source.AddHook(Hook);Registered=shellMessage!=0&&RegisterShellHookWindow(handle);poll=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};poll.Tick+=(o,e)=>Poll();poll.Start();Refresh();if(!Program.Testing&&!Program.ResizeCheck&&!Program.StatusCheck&&!Program.UiCheck){if(Enabled&&Registered)TaskbarAlerts.Apply();else TaskbarAlerts.Restore();}Record();}
 IntPtr Hook(IntPtr h,int message,IntPtr wp,IntPtr lp,ref bool handled){if(message==shellMessage){int code=wp.ToInt32();if(code==0x8006)Receive(lp);else if(code==4||code==0x8004)Poll();else if(code==2)RemoveWindow(lp);}return IntPtr.Zero;}
 public void Receive(IntPtr window){FlashEvents++;long last;if(stopped.TryGetValue(window,out last)&&(Stopwatch.GetTimestamp()-last)/(double)Stopwatch.Frequency<.15)return;if(!Enabled||window==IntPtr.Zero||!IsWindow(window)){Record();return;}string exe=Executable(window);var ids=targets.Where(pair=>Matches(pair.Value,exe)).Select(pair=>pair.Key).ToArray();if(ids.Length==0){Record();return;}MatchedEvents++;Stop(window);if(!String.Equals(Executable(Native.GetForegroundWindow()),exe,StringComparison.OrdinalIgnoreCase)){foreach(string id in ids)if(!PendingApps.ContainsKey(id))PendingApps[id]=new Pending{Id=id,Executable=exe,Window=window,Started=Stopwatch.GetTimestamp()};dock.ShowAttentionIcon(ids.First());dock.WakeAttention();}Record();}
 void Stop(IntPtr window){stopped[window]=Stopwatch.GetTimestamp();var info=new FlashInfo{cbSize=(uint)Marshal.SizeOf(typeof(FlashInfo)),hwnd=window,flags=0};FlashWindowEx(ref info);StopRequests++;}
 void RemoveWindow(IntPtr window){stopped.Remove(window);bool changed=false;foreach(string id in PendingApps.Where(pair=>pair.Value.Window==window).Select(pair=>pair.Key).ToArray()){PendingApps.Remove(id);changed=true;}if(changed)dock.WakeAttention();Record();}
 public void Poll(){if(disposed)return;string foreground=Executable(Native.GetForegroundWindow());bool changed=false;foreach(var pair in PendingApps.ToArray()){var pending=pair.Value;if(!IsWindow(pending.Window)||String.Equals(foreground,pending.Executable,StringComparison.OrdinalIgnoreCase)){if(IsWindow(pending.Window))Stop(pending.Window);PendingApps.Remove(pair.Key);changed=true;}}if(changed)dock.WakeAttention();if(changed||Program.PanelCheck)Record();}
 public void Acknowledge(string id){Pending pending;if(PendingApps.TryGetValue(id,out pending)){if(IsWindow(pending.Window))Stop(pending.Window);PendingApps.Remove(id);dock.WakeAttention();Record();}}
 public bool TryOpen(string id){Pending pending;if(!PendingApps.TryGetValue(id,out pending)||!IsWindow(pending.Window))return false;bool focused=CodexActivation.Focus(pending.Window);try{File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"dock-attention-activation.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),id,target=pending.Window.ToInt64(),foreground=Native.GetForegroundWindow().ToInt64(),focused,action="reuse-attention-window-no-launch"}),Encoding.UTF8);}catch{}if(focused)Acknowledge(id);return true;}
 public static double Bounce(double seconds){double phase=seconds%3.2;if(phase<0||phase>=1.1)return 0;return -13*Math.Abs(Math.Sin(Math.PI*phase/.55))*Math.Exp(-phase*.65);}
 public double Offset(string id){Pending pending;return Enabled&&PendingApps.TryGetValue(id,out pending)?Bounce((Stopwatch.GetTimestamp()-pending.Started)/(double)Stopwatch.Frequency):0;}
 public void Toggle(){Enabled=!Enabled;PendingApps.Clear();if(!Program.Testing&&!Program.ResizeCheck){if(Enabled&&Registered)TaskbarAlerts.Apply();else TaskbarAlerts.Restore();}File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"dock-attention-options.json"),new JavaScriptSerializer().Serialize(new{enabled=Enabled}),Encoding.UTF8);dock.WakeAttention();Record();}
 public MenuItem Menu(){var item=new MenuItem{Header="底栏图标跳动提醒（关闭可恢复任务栏提醒）",IsCheckable=true,IsChecked=Enabled};item.Click+=(o,e)=>Toggle();return item;}
 public object Info(){return new{time=DateTimeOffset.Now.ToString("o"),enabled=Enabled,registered=Registered,shellMessage,flashEvents=FlashEvents,matchedEvents=MatchedEvents,stopRequests=StopRequests,targets=targets.Select(p=>new{id=p.Key,executable=p.Value}).ToArray(),pending=PendingApps.Values.Select(p=>new{id=p.Id,handle=p.Window.ToInt64(),executable=p.Executable,offset=Offset(p.Id)}).ToArray(),visuals=Program.PanelCheck?dock.AttentionVisuals():null,scope="Shell HSHELL_FLASH; executable identity only; no message content; foreground or click clears"};}
 void Record(){if(disposed)return;try{File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"dock-attention-state.json"),new JavaScriptSerializer().Serialize(Info()),Encoding.UTF8);}catch{}}
 public void Dispose(){disposed=true;if(poll!=null)poll.Stop();if(Registered)DeregisterShellHookWindow(handle);if(source!=null)source.RemoveHook(Hook);PendingApps.Clear();if(!Program.Testing&&!Program.ResizeCheck&&!Program.StatusCheck&&!Program.UiCheck)TaskbarAlerts.Restore();}
}
public static class TaskbarAlerts {
 const string Key=@"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";static readonly string[] Names={"TaskbarFlashing","TaskbarBadges"};
 public class Previous {public string Name;public bool Existed;public int Value;}
 static string Backup{get{return System.IO.Path.Combine(Program.S.Root,"taskbar-alerts-backup.json");}}
 [DllImport("user32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr SendMessageTimeout(IntPtr h,uint msg,IntPtr wp,string lp,uint flags,uint timeout,out IntPtr result);
 static void Notify(){IntPtr result;SendMessageTimeout(new IntPtr(0xffff),0x1a,IntPtr.Zero,"TraySettings",2,1000,out result);}
