public static class BatteryVisual {
 public static ImageSource Create(double? level,bool online,bool present){
  var drawing=new DrawingGroup();using(var dc=drawing.Open()){
   var outline=new Pen(new SolidColorBrush(Color.FromRgb(224,235,238)),1.1);dc.DrawRoundedRectangle(new SolidColorBrush(Color.FromArgb(145,18,27,30)),outline,new Rect(1,3,27,14),3,3);dc.DrawRoundedRectangle(outline.Brush,null,new Rect(29,7,2,6),1,1);
   if(!present){dc.DrawLine(outline,new Point(9,10),new Point(21,10));}
   else if(level.HasValue){double amount=Math.Max(0,Math.Min(1,level.Value));var fill=new SolidColorBrush(amount<=.2?Color.FromRgb(241,87,81):amount<=.4?Color.FromRgb(243,189,76):Color.FromRgb(96,205,119));if(amount>0)dc.DrawRoundedRectangle(fill,null,new Rect(3.4,5.4,22.2*amount,9.2),1.5,1.5);}
   else{dc.DrawText(new FormattedText("?",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),11,outline.Brush,1),new Point(11,2));}
   if(online&&present){var bolt=Geometry.Parse("M17,0 L11,10 L16,10 L13,20 L22,7 L17,7 Z");dc.DrawGeometry(new SolidColorBrush(Color.FromRgb(232,247,239)),new Pen(new SolidColorBrush(Color.FromRgb(30,51,40)),.9),bolt);}
  }drawing.Freeze();var image=new DrawingImage(drawing);image.Freeze();return image;
 }
 public static ImageSource Current(){var power=Forms.SystemInformation.PowerStatus;bool present=(power.BatteryChargeStatus&Forms.BatteryChargeStatus.NoSystemBattery)==0;float value=power.BatteryLifePercent;return Create(value>=0&&value<=1?(double?)value:null,power.PowerLineStatus==Forms.PowerLineStatus.Online,present);}
 public static string ShortText(){var power=Forms.SystemInformation.PowerStatus;if((power.BatteryChargeStatus&Forms.BatteryChargeStatus.NoSystemBattery)!=0)return "已接通电源";float value=power.BatteryLifePercent;return value>=0&&value<=1?Math.Round(value*100)+"%":"电量未知";}
}
