  bool red=true;var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(3)};timer.Tick+=(o,e)=>{red=!red;near.Background=red?Brushes.DarkRed:Brushes.DarkBlue;label.Text=red?"IMMEDIATE RED":"IMMEDIATE BLUE";if(focus!=null){if(red)box.Activate();else focus.Activate();File.WriteAllText(System.IO.Path.Combine(Program.S.Root,"frame-phase.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),mainActive=box.IsActive,material=Native.PanelMaterialInfo(box)}),Encoding.UTF8);}};timer.Start();
