namespace DesktopBox {
public static class ControlMaterialTests {
 public static async System.Threading.Tasks.Task Run(Box box,Action<string,bool> check){var center=new ControlCenter(box,box.Dock);var neutral=new Window{Title="控制中心焦点切换隔离窗口",Width=220,Height=130,ShowInTaskbar=false};try{center.Reveal();center.GlassSlider.Value=100;center.UpdateLayout();center.UpdateLayer();await System.Threading.Tasks.Task.Delay(100);int initialRegion=center.Material.RegionChanges,initialPosition=center.Material.PositionChanges;for(int i=0;i<30;i++)center.UpdateLayer();check("控制中心原生鼠标激活被禁止且不丢弃点击",Native.SendMessage(new WindowInteropHelper(center).Handle,0x21,IntPtr.Zero,IntPtr.Zero).ToInt32()==3);check("控制中心和玻璃层的系统过渡禁用请求均被接受",Native.TransitionsDisabledRequested(new WindowInteropHelper(center).Handle)&&Native.TransitionsDisabledRequested(new IntPtr(center.Material.Handle)));check("控制中心鼠标控件不强制键盘焦点且滑条仍启用",!center.Focusable&&!center.GlassSlider.Focusable&&center.GlassSlider.IsEnabled&&center.VolumeSlider.IsEnabled&&center.BrightnessSlider.IsEnabled);check("控制中心背景不变时重复维护不重建圆角和不重新显示定位",center.Material.RegionChanges==initialRegion&&center.Material.PositionChanges==initialPosition);center.LowerGlassToDesktop();int firstBatches=center.Material.LayerBatches;for(int i=0;i<20;i++)center.LowerGlassToDesktop();check("重复放回桌面时玻璃与内容保持同一组且不重复调整",center.Material.Ready&&center.Material.LayerBatches==firstBatches);var frames=new List<object>();bool stable=true;neutral.Show();for(int turn=0;turn<8;turn++){center.Activate();await System.Threading.Tasks.Task.Delay(15);neutral.Activate();Native.LowerToDesktop(center);center.UpdateLayer();await System.Threading.Tasks.Task.Delay(15);var state=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(center.Material.Info()));stable&=(bool)state["ready"]&&(bool)state["visible"]&&(bool)state["directlyBelowPanel"]&&state["error"].ToString()==""&&center.Material.RegionChanges==initialRegion&&Native.Above(neutral,center);frames.Add(state);}check("反复切换焦点后控制中心玻璃不隐藏且普通窗口仍可覆盖",stable);double width=center.Width;center.Width=width+24;center.UpdateLayout();center.UpdateLayer();check("真实尺寸变化仍会更新玻璃圆角范围",center.Material.RegionChanges>initialRegion);center.Hide();center.UpdateLayer();var hidden=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(center.Material.Info()));check("关闭控制中心仍同步隐藏玻璃层",!(bool)hidden["visible"]);center.Reveal();center.UpdateLayer();var shown=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(center.Material.Info()));check("再次打开控制中心恢复同一玻璃层",(bool)shown["visible"]&&center.Material.Ready);File.WriteAllText(System.IO.Path.Combine(Program.OutDir,"控制中心玻璃稳定核对.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),initialRegion,initialPosition,firstBatches,frames,final=center.Material.Info(),scope="Own isolated WPF control center; repeated shared updates, focus activation and desktop placement with native visibility/z-order checks. Not a screen-recording or physical click flicker measurement."}),Encoding.UTF8);}finally{neutral.Close();center.PrepareExit();center.Close();}}
}
}
